node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check for carts table
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('=== TABLES ===');
tables.forEach(t => console.log('  ' + t.name));

// Check cart for cust_001
console.log('\n=== CARTS ===');
try {
    const carts = db.prepare('SELECT * FROM carts').all();
    carts.forEach(c => console.log('  ' + JSON.stringify(c)));
} catch(e) { console.log('  Error: ' + e.message); }

// Check cart_items
console.log('\n=== CART_ITEMS ===');
try {
    const items = db.prepare('SELECT * FROM cart_items').all();
    items.forEach(i => console.log('  ' + JSON.stringify(i)));
} catch(e) { console.log('  Error: ' + e.message); }

// Check user's skill mapping for shopping
console.log('\n=== USER SKILL MAPPING ===');
const user = db.prepare('SELECT user_id, name, skill_ids_json FROM users WHERE user_id = ?').get('cust_001');
if (user) console.log('  ' + JSON.stringify(user));

// Look for shopping-scoped users
console.log('\n=== SHOPPING-SCOPED USERS ===');
const shopUsers = db.prepare(\"SELECT user_id, name, skill_ids_json FROM users WHERE skill_ids_json LIKE '%state-shopping%'\").all();
shopUsers.forEach(u => console.log('  ' + JSON.stringify(u)));

db.close();
"

