node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const customerId = 'user_1b350225';
const productId = 'PROD-73FAB4';
const cartId = 'CART-' + customerId;

// --- Step 1: Add product to cart ---

// Get current cart
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
const currentItemIds = JSON.parse(cart.item_ids_json || '[]');

// Find next cart_item_id
const maxCI = db.prepare(\"SELECT cart_item_id FROM cart_items ORDER BY cart_item_id DESC LIMIT 1\").get();
const lastSeq = maxCI ? parseInt(maxCI.cart_item_id.replace('CI-', '')) : 0;
const newCIId = 'CI-' + String(lastSeq + 1).padStart(4, '0');

console.log('=== STEP 1: ADD TO CART ===');
console.log('New cart item ID: ' + newCIId);

// Insert cart item
db.prepare(
    'INSERT INTO cart_items (cart_item_id, cart_id, customer_id, product_id, quantity, gift_wrap, variant_id) VALUES (?,?,?,?,?,?,?)'
).run(newCIId, cartId, customerId, productId, 1, 0, null);

// Update cart item_ids
currentItemIds.push(newCIId);

// --- Step 2: Apply ELEC15 promo ---

// Get promo details
const promo = db.prepare('SELECT * FROM promotions WHERE promo_code = ?').get('ELEC15');
console.log('\n=== STEP 2: APPLY PROMO ===');
console.log('Promo: ' + promo.description);

// --- Step 3: Recompute cart totals ---

// Get product price
const product = db.prepare('SELECT price FROM products WHERE product_id = ?').get(productId);
const subtotal = product.price * 1; // qty 1
const giftWrapFee = 0; // no gift wrap

// Calculate promo discount: 15% of subtotal, max $50
const discountRaw = Math.floor(subtotal * promo.discount_value / 100);
const discountAmount = promo.max_discount > 0 ? Math.min(discountRaw, promo.max_discount) : discountRaw;

// Total (no shipping set yet, no loyalty discount)
const total = Math.max(0, subtotal + giftWrapFee - discountAmount);

console.log('Subtotal: $' + subtotal);
console.log('Discount (15%): -$' + discountAmount);
console.log('Total: $' + total);

// Update cart
db.prepare(
    'UPDATE carts SET subtotal=?, discount_amount=?, gift_wrap_fee=?, total=?, applied_promo_codes_json=?, item_ids_json=? WHERE cart_id=?'
).run(subtotal, discountAmount, giftWrapFee, total, JSON.stringify(['ELEC15']), JSON.stringify(currentItemIds), cartId);

console.log('\n=== STEP 3: VERIFY UPDATED CART ===');
const updatedCart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
console.log(JSON.stringify(updatedCart, null, 2));

const cartItems = db.prepare('SELECT ci.*, p.name, p.price, p.brand FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.customer_id = ?').all(customerId);
console.log('\n=== CART ITEMS ===');
cartItems.forEach(i => console.log(JSON.stringify(i, null, 2)));

db.close();
console.log('\nDone!');
"
